int can_send_credentials(struct ucred *creds) {
    uid_t euid = geteuid();
    gid_t egid = getegid();

    if (creds->uid != euid || creds->gid != egid) {
        if (!capable(CAP_ADMIN)) {
            if (creds->uid == 0 || creds->gid == 0) {
                return -EINVAL;
            }
            return -EPERM;
        }
    }

    return 0;
}

int check_creds_send(struct ucred *creds) {
    int current_uid = getuid();
    int current_gid = getgid();
    int has_admin_caps = 0;

    if (geteuid() == 0) {
        has_admin_caps = 1;
    }

    if (creds->uid != current_uid && !has_admin_caps) {
        return -EPERM;
    }

    if (creds->gid != current_gid && !has_admin_caps) {
        return -EPERM;
    }

    if (creds->uid < 0 || creds->gid < 0) {
        return -EINVAL;
    }

    return 0;
}

