int can_send_credentials(struct ucred *creds) {
    uid_t current_uid = getuid();
    gid_t current_gid = getgid();
    int has_admin = (geteuid() == 0);

    if (creds == NULL) {
        return -EINVAL;
    }

    if ((creds->uid != current_uid || creds->gid != current_gid) && !has_admin) {
        return -EPERM;
    }

    return 0;
}
